exercises.solution:
def early_stop(losses, patience):
    best, best_epoch, wait = float("inf"), -1, 0
    for epoch, loss in enumerate(losses):
        if loss < best:
            best, best_epoch, wait = loss, epoch, 0
        else:
            wait += 1
            if wait >= patience:
                return [epoch, best_epoch]
    return [None, best_epoch]
